void apply_hebbian(float* nucleus, int size, float* input, int input_size,
    float output, float lr) {
    for (int i = 0; i < size && i < input_size; i++) {
        nucleus[i] += lr * input[i] * output;
        nucleus[i] = tanhf(nucleus[i]);
    }
}

void apply_stdp(float* nucleus, int size, float* input, int input_size,
    float output, float lr) {
    float dt = output - 0.5f;
    for (int i = 0; i < size && i < input_size; i++) {
        float dw = lr * input[i] * dt * expf(-fabsf((float)i * dt));
        nucleus[i] += dw;
        nucleus[i] = tanhf(nucleus[i]);
    }
}

