/* ========= Event-Driven Runtime ========= */
typedef struct {
    int neuron_id;
    int time;
    float strength;
    int source_id;
} SpikeEvent;

#define MAX_EVENTS 10000
typedef struct { int post; float weight; int delay; } Synapse;

static int event_head = 0, event_tail = 0;

static int event_queue_full(int tail) {
    return ((tail + 1) % MAX_EVENTS) == event_head;
}

static void event_queue_push(SpikeEvent* q, int* tail, SpikeEvent ev) {
    if (event_queue_full(*tail)) return;
    int pos = *tail;
    q[pos] = ev;
    *tail = (*tail + 1) % MAX_EVENTS;
}

static void event_queue_insert_sorted(SpikeEvent* q, int* head, int* tail, SpikeEvent ev) {
    if (event_queue_full(*tail)) return;
    if (*head == *tail) { event_queue_push(q, tail, ev); return; }
    int count = (*tail - *head + MAX_EVENTS) % MAX_EVENTS;
    int insert_at = *tail;
    for (int i = 0; i < count; i++) {
    int idx = (*head + i) % MAX_EVENTS;
    if (q[idx].time > ev.time) { insert_at = idx; break; }
}
/* shift tail forward */
if (!event_queue_full(*tail)) {
    int t = *tail;
    int stop = insert_at;
    while (t != stop) {
    int prev = (t - 1 + MAX_EVENTS) % MAX_EVENTS;
    q[t] = q[prev];
    t = prev;
}
q[insert_at] = ev;
*tail = (*tail + 1) % MAX_EVENTS;
}
}

static void inject_input(SpikeEvent* q, int* head, int* tail, float* input, int n, int current_time) {
    for (int i = 0; i < n; i++) {
    if (fabsf(input[i]) < 1e-6f) continue;
    SpikeEvent ev = { .neuron_id = i, .time = current_time,
        .strength = input[i], .source_id = -1 };
    event_queue_insert_sorted(q, head, tail, ev);
}
}

